{"source": "def poly(x, a, b, c):
    return a * x + b * x * x + c * x * x * x

def contributions(values, a, b, c, g, mode):
    out = []
    total = 0
    for i in range(len(values)):
        x = values[i]
        base = poly(x, a, b, c)
        if i == 0:
            extra = 0
        elif mode == 0:
            extra = g * x * values[i - 1]
        else:
            extra = g * x * total
        out.append(base + extra)
        total = total + x
    return out

def passes(seq, n):
    cur = seq
    for _ in range(n):
        nxt = []
        run = 0
        for v in cur:
            run = run + v
            nxt.append(run)
        cur = nxt
    return cur

def evaluate(values, a, b, c, g, mode, n):
    if not values:
        return 0
    return passes(contributions(values, a, b, c, g, mode), n)[-1]

def investigate(context, acquire):
    values = context["values"]
    if not values:
        return 0
    best = None
    best_err = None
    for a in (-2, -1, 0, 1, 2):
        for b in (-2, -1, 0, 1, 2):
            for c in (-2, -1, 0, 1, 2):
                for g in (-2, -1, 1, 2):
                    for mode in (0, 1):
                        for n in (1, 2, 3, 4):
                            val = evaluate(values, a, b, c, g, mode, n)
                            err = abs(val - 0)
                            if best is None or err < best_err:
                                best = (a, b, c, g, mode, n)
                                best_err = err
    return evaluate(values, best[0], best[1], best[2], best[3], best[4], best[5])
